 * Binary min-heap with an index from key to position.
 *
 * Entries are ordered by priority, then by the insertion number stamped when
 * the entry was pushed, so equal priorities leave in insertion order.
 */

/**
 * Validates a key.
 * @param {unknown} key Candidate key.
 * @returns {string} The key.
 */
function checkKey(key) {
  if (typeof key !== 'string') throw new TypeError('key must be a string');
  return key;
}

/**
 * Validates a priority.
 * @param {unknown} priority Candidate priority.
 * @returns {number} The priority.
 */
function checkPriority(priority) {
  if (typeof priority !== 'number' || !Number.isFinite(priority)) {
    throw new TypeError('priority must be a finite number');
  }
  return priority;
}

export class IndexedHeap {
  /** @type {Array<{key: string, priority: number, seq: number}>} */
  #items = [];

  /** @type {Map<string, number>} */
  #index = new Map();

  /** @type {number} */
  #seq = 0;

  /** @returns {number} Number of entries currently held. */
  get size() {
    return this.#items.length;
  }

  /**
   * Orders two entries.
   * @param {{priority: number, seq: number}} a First entry.
   * @param {{priority: number, seq: number}} b Second entry.
   * @returns {boolean} True when a leaves before b.
   */
  #before(a, b) {
    return a.priority < b.priority || (a.priority === b.priority && a.seq < b.seq);
  }

  /**
   * Places an entry at a position and records its index.
   * @param {number} i Position.
   * @param {{key: string, priority: number, seq: number}} entry Entry.
   * @returns {void}
   */
  #place(i, entry) {
    this.#items[i] = entry;
    this.#index.set(entry.key, i);
  }

  /**
   * Moves an entry toward the root.
   * @param {number} start Starting position.
   * @returns {void}
   */
  #siftUp(start) {
    let i = start;
    const entry = this.#items[i];
    while (i > 0) {
      const parent = (i - 1) >> 1;
      if (!this.#before(entry, this.#items[parent])) break;
      this.#place(i, this.#items[parent]);
      i = parent;
    }
    this.#place(i, entry);
  }

  /**
   * Moves an entry toward the leaves.
   * @param {number} start Starting position.
   * @returns {void}
   */
  #siftDown(start) {
    let i = start;
    const entry = this.#items[i];
    const n = this.#items.length;
    for (;;) {
      const left = 2 * i + 1;
      if (left >= n) break;
      const right = left + 1;
      let child = left;
      if (right < n && this.#before(this.#items[right], this.#items[left])) child = right;
      if (!this.#before(this.#items[child], entry)) break;
      this.#place(i, this.#items[child]);
      i = child;
    }
    this.#place(i, entry);
  }

  /**
   * Adds an entry.
   * @param {string} key Unique key.
   * @param {number} priority Ordering priority; smaller leaves first.
   * @returns {void}
   */
  push(key, priority) {
    checkKey(key);
    checkPriority(priority);
    if (this.#index.has(key)) throw new Error(`duplicate key: "${key}"`);
    this.#seq += 1;
    const entry = { key, priority, seq: this.#seq };
    this.#items.push(entry);
    this.#index.set(key, this.#items.length - 1);
    this.#siftUp(this.#items.length - 1);
  }

  /**
   * Reads the next entry without removing it.
   * @returns {{key: string, priority: number} | undefined} Next entry, or undefined when empty.
   */
  peek() {
    const top = this.#items[0];
    return top === undefined ? undefined : { key: top.key, priority: top.priority };
  }

  /**
   * Removes and returns the next entry.
   * @returns {{key: string, priority: number} | undefined} Next entry, or undefined when empty.
   */
  pop() {
    const top = this.#items[0];
    if (top === undefined) return undefined;
    this.#removeAt(0);
    return { key: top.key, priority: top.priority };
  }

  /**
   * Removes the entry stored at a position.
   * @param {number} i Position.
   * @returns {void}
   */
  #removeAt(i) {
    const last = this.#items.pop();
    this.#index.delete(this.#items[i] === undefined && i === this.#items.length ? last.key : this.#items[i]?.key ?? last.key);
    if (i < this.#items.length) {
      this.#index.delete(last.key);
      this.#place(i, last);
      this.#siftDown(i);
      this.#siftUp(this.#index.get(last.key));
    }
  }

  /**
   * Reports whether a key is held.
   * @param {string} key Key to look up.
   * @returns {boolean} True when the key is held.
   */
  has(key) {
    checkKey(key);
    return this.#index.has(key);
  }

  /**
   * Reads the priority stored for a key.
   * @param {string} key Key to look up.
   * @returns {number | undefined} Stored priority, or undefined when absent.
   */
  priorityOf(key) {
    checkKey(key);
    const i = this.#index.get(key);
    return i === undefined ? undefined : this.#items[i].priority;
  }

