   * Empties the heap.
   * @returns {Array<{key: string, priority: number}>} Every entry in pop order.
   */
  drain() {
    const out = [];
    for (;;) {
      const next = this.pop();
      if (next === undefined) break;
      out.push(next);
    }
    return out;
  }
