 * Single-source shortest paths over a weighted directed graph, driven by the
 * indexed heap so a shorter route to a queued node lowers its priority in
 * place instead of enqueueing a duplicate.
 */

import { IndexedHeap } from './heap.js';

/** Infinity, as it appears in a distance map. */
const FAR = Number.POSITIVE_INFINITY;

/**
 * Reports whether a value is a non-null, non-array object.
 * @param {unknown} value Candidate value.
 * @returns {boolean} True when the value qualifies.
 */
function isObject(value) {
  return typeof value === 'object' && value !== null && !Array.isArray(value);
}

/**
 * Validates a graph.
 * @param {unknown} graph Candidate graph.
 * @returns {Record<string, Record<string, number>>} The graph.
 */
function checkGraph(graph) {
  if (!isObject(graph)) throw new TypeError('graph must be an object');
  const g = /** @type {Record<string, unknown>} */ (graph);
  for (const node of Object.keys(g)) {
    const edges = g[node];
    if (!isObject(edges)) throw new TypeError(`edge map for node "${node}" must be an object`);
    for (const [target, weight] of Object.entries(/** @type {Record<string, unknown>} */ (edges))) {
      if (!Object.hasOwn(g, target)) throw new ReferenceError(`unknown node: "${target}"`);
      if (typeof weight !== 'number' || !Number.isFinite(weight) || weight <= 0) {
        throw new RangeError(`weight must be positive: "${node}" -> "${target}"`);
      }
    }
  }
  return /** @type {Record<string, Record<string, number>>} */ (graph);
}

/**
 * Validates a node id against a graph.
 * @param {Record<string, Record<string, number>>} graph Graph.
 * @param {unknown} node Candidate node.
 * @param {string} label Name used in the type error.
 * @returns {string} The node id.
 */
function checkNode(graph, node, label) {
  if (typeof node !== 'string') throw new TypeError(`${label} must be a string`);
  if (!Object.hasOwn(graph, node)) throw new ReferenceError(`unknown node: "${node}"`);
  return node;
}

/**
 * Computes the distance and predecessor of every node from one source.
 * @param {unknown} graph Weighted directed graph.
 * @param {string} source Node to start from.
 * @returns {{dist: Record<string, number>, prev: Record<string, string | null>}} Distances and predecessors.
 */
export function shortestPaths(graph, source) {
  const g = checkGraph(graph);
  const start = checkNode(g, source, 'source');
  const nodes = Object.keys(g);

  /** @type {Record<string, number>} */
  const dist = {};
  for (const node of nodes) dist[node] = FAR;
  dist[start] = 0;

  const settled = new Set();
  const heap = new IndexedHeap();
  heap.push(start, 0);

  for (;;) {
    const next = heap.pop();
    if (next === undefined) break;
    const node = next.key;
    settled.add(node);
    for (const [target, weight] of Object.entries(g[node])) {
      if (settled.has(target)) continue;
      const candidate = dist[node] + weight;
      if (candidate < dist[target]) {
        dist[target] = candidate;
        if (heap.has(target)) heap.decreaseKey(target, candidate);
        else heap.push(target, candidate);
      }
    }
  }

