  // realise a node's distance, name the smallest source id.
  /** @type {Record<string, string | null>} */
  const prev = {};
  for (const node of nodes) prev[node] = null;
  for (const node of [...nodes].sort()) {
    if (dist[node] === FAR) continue;
    for (const [target, weight] of Object.entries(g[node])) {
      if (target === start || prev[target] !== null) continue;
      if (dist[node] + weight === dist[target]) prev[target] = node;
    }
  }

  return { dist, prev };
}

