 * Finds one shortest route between two nodes.
 * @param {unknown} graph Weighted directed graph.
 * @param {string} source Node to start from.
 * @param {string} target Node to reach.
 * @returns {{distance: number, path: string[]} | null} Route, or null when unreachable.
 */
export function shortestPath(graph, source, target) {
  const g = checkGraph(graph);
  checkNode(g, source, 'source');
  const goal = checkNode(g, target, 'target');
  const { dist, prev } = shortestPaths(g, source);
  if (dist[goal] === FAR) return null;
  const path = [goal];
  let node = goal;
  while (prev[node] !== null) {
    node = /** @type {string} */ (prev[node]);
    path.push(node);
  }
  path.reverse();
  return { distance: dist[goal], path };
}
